  float h1 = snoise(vec2(uv.x * 4.0 + t * 0.8, uv.y * 7.0 - t * 1.5)) * 0.4;
  float h2 = snoise(vec2(uv.x * 7.0 - t * 0.5, uv.y * 3.0 + 2.3)) * 0.25;

  vec2 distort;
  distort.x = (h1 + h2) * intensity * 0.025;
  distort.y = (n1 + n2 + n3) * intensity * 0.018;

