}

// ── Ridged noise for veins ──
float ridged(vec2 p, int octaves) {
  float v = 0.0, a = 0.5;
  mat2 rot = mat2(0.8, 0.6, -0.6, 0.8);
  for (int i = 0; i < 6; i++) {
    if (i >= octaves) break;
    float n = vnoise(p);
    n = 1.0 - abs(n * 2.0 - 1.0);
    n = n * n;
