  float horizonDist = abs(uv.y - HORIZON);
  float hazeMask = exp(-horizonDist * 15.0);
  float hazeVal = haze(uv, t);
  col += vec3(0.5, 0.15, 0.4) * hazeVal * hazeMask * 0.15;

