  col *= u_glow;

  // Vignette
  col *= vignette(uv);

  // Subtle scanlines for CRT feel
  col *= scanlines(gl_FragCoord.xy);

  // Tone mapping — slight S-curve for richer darks
  col = col / (col + vec3(0.8));
  col = pow(col, vec3(0.95));

  // Very slight chromatic shift at edges
  float chromDist = length(uv * vec2(0.5, 0.7));
  float chromShift = chromDist * 0.003;
  vec3 finalCol;
  vec2 uvR = (gl_FragCoord.xy + vec2(chromShift * u_res.y, 0.0) - u_res * 0.5) / u_res.y;
  vec2 uvB = (gl_FragCoord.xy - vec2(chromShift * u_res.y, 0.0) - u_res * 0.5) / u_res.y;

  // Only apply chroma to the final composite for performance
  finalCol.r = col.r * (1.0 + chromShift * 2.0);
  finalCol.g = col.g;
  finalCol.b = col.b * (1.0 + chromShift * 2.0);

  gl_FragColor = vec4(finalCol, 1.0);
}

